[
    {
        "title": "看清两杯水",
        "description": "两个容器相同，容器A原来装满，记作 $1$；容器B原来只有一半，记作 $\\frac12$。",
        "bubbleText": "先把“满杯”看成 $1$ 份，这样A有 $1$ 份，B现在有 $\\frac12$ 份。",
        "bubblePos": {
            "x": 205,
            "y": 135
        }
    },
    {
        "title": "找到B差多少",
        "description": "容器B要装满，还差 $1-\\frac12=\\frac12$。",
        "bubbleText": "B现在只有半杯，要变成满杯，就还缺另外半杯，也就是 $\\frac12$。",
        "bubblePos": {
            "x": 575,
            "y": 455
        }
    },
    {
        "title": "确定该倒多少",
        "description": "题目说从A倒入B，使B正好装满，所以从A倒出的水量正好等于B缺少的水量，即 $\\frac12$。",
        "bubbleText": "B缺多少，就从A倒多少；既然B缺 $\\frac12$，那A就要倒出 $\\frac12$ 杯。",
        "bubblePos": {
            "x": 390,
            "y": 180
        }
    },
    {
        "title": "和A作比较",
        "description": "容器A原来有满满的 $1$ 杯，倒出了 $\\frac12$ 杯，所以倒出的水量是A中水的 $\\frac12$。",
        "bubbleText": "别忘了问题问的是“占A的多少”。A原来是 $1$，倒出的是 $\\frac12$，所以占A的 $\\frac12$。",
        "bubblePos": {
            "x": 385,
            "y": 315
        }
    },
    {
        "title": "写出答案",
        "description": "应该倒入容器B的水量是容器A中的 $\\frac12$。",
        "bubbleText": "答案就是一半，也可以说“倒A里水的二分之一到B里”。",
        "bubblePos": {
            "x": 385,
            "y": 470
        }
    },
    {
        "title": "验证是否正确",
        "description": "验证：B原有 $\\frac12$，再倒入 $\\frac12$，得到 $\\frac12+\\frac12=1$，正好装满，说明答案正确。",
        "bubbleText": "检查一下：半杯加半杯等于一整杯，B刚好满了，所以我们求对了！",
        "bubblePos": {
            "x": 675,
            "y": 165
        }
    }
]
